// Filtrar solo la rutina de hoy que NO esté completada
// Calculamos midnight de hoy en Bogota, expresado en UTC
const todayMidnightUTC = $now.setZone('America/Bogota').startOf('day').toUTC();
const items = $input.all();

const todayRoutine = items.filter(item => {
  // planned_day_utc es TIMESTAMPTZ (midnight Bogota en UTC = 05:00:00Z)
  // planned_day puede ser ISO (YYYY-MM-DD) o DD/MM o DD/MM/YYYY
  let plannedDate;
  if (item.json.planned_day_utc) {
    plannedDate = new Date(item.json.planned_day_utc);
  } else if (item.json.planned_day) {
    const parts = item.json.planned_day.split('/');
    const day = parseInt(parts[0], 10);
    const month = parseInt(parts[1], 10) - 1;
    const year = parts[2] ? parseInt(parts[2], 10) : new Date().getFullYear();
    plannedDate = new Date(Date.UTC(year, month, day, 5, 0, 0));
  } else {
    return false;
  }
  const todayDate = new Date(todayMidnightUTC.toISO());

  // Comparar timestamps (ambos deberían ser midnight Bogota en UTC)
  const isToday = plannedDate.getTime() === todayDate.getTime();

  // Completed puede ser booleano false o string 'false'
  const isNotCompleted = item.json.Completed === false || item.json.Completed === 'false';

  return isToday && isNotCompleted;
});

// Si no hay rutina para hoy sin completar, retornar array vacío
return todayRoutine.length > 0 ? todayRoutine : [];

// Normalize WhatsApp message input - handles text and button messages
const items = $input.all();

return items.map(item => {
  const message = item.json.messages?.[0];
  if (!message) return item;

  let messageBody = '';

  switch (message.type) {
    case 'text':
      messageBody = message.text?.body ?? '';
      break;
    case 'button':
      messageBody = message.button?.payload ?? message.button?.text ?? '';
      break;
    case 'interactive':
      // Future-proofing for interactive buttons/lists
      messageBody = message.interactive?.button_reply?.title ??
                    message.interactive?.list_reply?.title ?? '';
      break;
    default:
      messageBody = message.text?.body ?? '';
  }

  return {
    json: {
      ...item.json,
      message_body: messageBody.trim()
    }
  };
});

// Mensaje filtrado (status update, audio, etc)
// Retornar objeto vacío para que el test runner pueda continuar
return [{ json: { filtered: true, output: '' } }];

// Build workout URL with short code
const items = $input.all();
const FRONTEND_URL = 'https://[FIREBASE_PROJECT_ID].web.app';

return items.map(item => ({
  json: {
    ...item.json,
    workout_url: `${FRONTEND_URL}/w?c=${item.json.code}`
  }
}));

// Verificar si el mesociclo esta completo (semana 4)
const weekSchedule = $items('Week_Schedule')[0]?.json;
const daysPerWeek = weekSchedule?.days_per_week || 0;

const finishedWorkouts = $('User_Finished_Workouts').all();

const week4Completed = finishedWorkouts.filter(
  w => w.json.week === 4 && w.json.Completed === true
).length;

const mesocycleComplete = daysPerWeek > 0 && week4Completed >= daysPerWeek;

return [{
  json: {
    mesocycle_complete: mesocycleComplete,
    week4_completed: week4Completed,
    days_per_week: daysPerWeek,
    user_id: weekSchedule?.user_id
  }
}];

// ---------- INPUT ----------
const allRows = $('GetCalendarData').all().map(i => i.json);
const magicCode = $('CreateCalendarMagicLink').first().json.code;
const magicUrl = `https://workout-tracker-69b08.web.app/w?c=${magicCode}`;

console.log('[PrepareCalendarEvents] rows:', allRows.length);
for (let i = 0; i < allRows.length; i++) {
  console.log(`[PrepareCalendarEvents] row[${i}] planned_day:`, JSON.stringify(allRows[i].planned_day), 'type:', typeof allRows[i].planned_day, 'session_duration_mins:', JSON.stringify(allRows[i].session_duration_mins));
}

if (allRows.length === 0) return [];

// ---------- CONFIG ----------
const timeMap = { 'Mañana': '06:00', 'Tarde': '16:00', 'Noche': '19:00' };
const roleLabels = { compound: 'EJERCICIOS COMPUESTOS', core: 'CORE', isolation: 'AISLAMIENTO' };
const roleOrder = ['compound', 'core', 'isolation'];

function parseDuration(str) {
  if (!str) return 60;
  const s = String(str);
  const match = s.match(/(\d+)\s*[-\u2013\u2014]\s*(\d+)/);
  if (match) return parseInt(match[2]);
  const single = s.match(/(\d+)/);
  return single ? parseInt(single[1]) : 60;
}

function parseDate(dateStr) {
  const now = DateTime.now().setZone('America/Bogota');
  if (!dateStr && dateStr !== 0) return now;
  const s = String(dateStr).trim();
  if (!s || s === 'null' || s === 'undefined') return now;

  console.log('[parseDate] input:', JSON.stringify(s));

  // ISO format: YYYY-MM-DD (must start with 4 digits)
  const isoMatch = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (isoMatch) {
    const yr = parseInt(isoMatch[1]);
    const mo = parseInt(isoMatch[2]);
    const dy = parseInt(isoMatch[3]);
    console.log('[parseDate] ISO parsed -> year:', yr, 'month:', mo, 'day:', dy);
    return DateTime.fromObject({ year: yr, month: mo, day: dy }, { zone: 'America/Bogota' });
  }

  // DD/MM or DD/MM/YYYY
  const slashMatch = s.match(/^(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?$/);
  if (slashMatch) {
    const dd = parseInt(slashMatch[1]);
    const mm = parseInt(slashMatch[2]);
    let year;
    if (slashMatch[3]) {
      year = parseInt(slashMatch[3]);
      if (year < 100) year += 2000;
    } else {
      year = now.year;
      if (mm < now.month) year += 1;
    }
    console.log('[parseDate] slash parsed -> year:', year, 'month:', mm, 'day:', dd);
    return DateTime.fromObject({ year, month: mm, day: dd }, { zone: 'America/Bogota' });
  }

  // Fallback: try Luxon fromISO as last resort
  console.log('[parseDate] no pattern matched, trying fromISO fallback');
  const attempt = DateTime.fromISO(s, { zone: 'America/Bogota' });
  if (attempt.isValid) return attempt;

  console.log('[parseDate] all parsing failed, returning today');
  return now;
}

function addMinutes(isoStr, mins) {
  return DateTime.fromISO(isoStr, { zone: 'America/Bogota' }).plus({ minutes: mins }).toFormat("yyyy-MM-dd'T'HH:mm:ss");
}

// ---------- GROUP BY DAY ----------
const dayMap = new Map();
for (const row of allRows) {
  const key = row.planned_day;
  if (!dayMap.has(key)) {
    dayMap.set(key, {
      day_routine_id: row.day_routine_id,
      session_name: row.session_name,
      planned_day: row.planned_day,
      week_day: row.week_day,
      email: row.email,
      full_name: row.full_name,
      preferred_schedule: row.preferred_schedule,
      session_duration_mins: row.session_duration_mins,
      training_environment: row.training_environment,
      exercises: []
    });
  }
  if (row.spanish_name) {
    dayMap.get(key).exercises.push({
      exercise_order: row.exercise_order,
      spanish_name: row.spanish_name,
      sets: row.sets,
      reps: row.reps,
      rir: row.rir,
      rest_seconds: row.rest_seconds,
      role: row.role || 'compound'
    });
  }
}

// ---------- BUILD EVENTS ----------
const events = [];
for (const [, day] of dayMap) {
  const startTime = timeMap[day.preferred_schedule] || '06:00';
  const durationMins = parseDuration(day.session_duration_mins);
  const date = parseDate(day.planned_day);
  const startDT = date.set({
    hour: parseInt(startTime.split(':')[0]),
    minute: parseInt(startTime.split(':')[1])
  }).toFormat("yyyy-MM-dd'T'HH:mm:ss");
  const endDT = addMinutes(startDT, durationMins);

  // Build description grouped by role
  let desc = 'Tu rutina del dia:\n\n';
  const byRole = {};
  for (const ex of day.exercises) {
    if (!byRole[ex.role]) byRole[ex.role] = [];
    byRole[ex.role].push(ex);
  }
  for (const role of roleOrder) {
    const exs = byRole[role];
    if (!exs || exs.length === 0) continue;
    const first = exs[0];
    const header = `${roleLabels[role] || role.toUpperCase()} (${first.sets} sets x ${first.reps} reps | RIR ${first.rir})`;
    desc += `${header}\n`;
    for (const ex of exs) {
      desc += `${ex.exercise_order}. ${ex.spanish_name}\n`;
    }
    desc += '\n';
  }
  desc += `Abre tu rutina: ${magicUrl}`;

  const location = (day.training_environment || 'GYM') === 'HOME' ? 'Casa' : 'Gimnasio';

  events.push({
    json: {
      day_routine_id: day.day_routine_id,
      summary: `${day.session_name} - Entrenamiento Kairos`,
      description: desc,
      startDateTime: startDT,
      endDateTime: endDT,
      attendeeEmail: day.email,
      location,
      timezone: 'America/Bogota'
    }
  });
}

return events;
